console.log('Final unique title list count:', titles.length);

// Sort by release date for releaseRank
const sortedByRelease = [...titles].sort((a, b) => a.releaseDate.localeCompare(b.releaseDate));
sortedByRelease.forEach((item, index) => {
  item.releaseRank = index + 1;
});

// Chronological rank
const sortedByChrono = [...titles].sort((a, b) => {
  if (a.year !== b.year) return a.year - b.year;
  return a.releaseDate.localeCompare(b.releaseDate);
});
sortedByChrono.forEach((item, index) => {
  item.chronologicalRank = index + 1;
});

// Phanteress bespoke rank
titles.forEach((item, index) => {
  // MCU core gets priority in bespoke order, followed by Spider-Verse, X-Men, then classics
  let score = index;
  if (item.inDoomsdayList) score -= 100;
  if (item.inFocusMcu) score -= 50;
  item.phanteressRank = score;
});
const sortedByPhanteress = [...titles].sort((a, b) => a.phanteressRank - b.phanteressRank);
sortedByPhanteress.forEach((item, index) => {
  item.phanteressRank = index + 1;
});

